    const P = this.inFrame(this.paFrame, S);
    for (const [x0, z0, x1, z1] of [[-50, -64, 34, -60], [81.5, -80, 88, 24], [-111, 46, -96, 52]]) P.add(planeGeo(x1 - x0, z1 - z0), grass, (x0 + x1) / 2, 0.03, (z0 + z1) / 2);
