    const [ex, ez] = L.entry;
    decal('徐行', ex - 14, 46.5, -Math.PI / 2, 2.6, 4.5); decal('↑', ex - 24, 46.5, -Math.PI / 2, 2, 5);
    decal('止まれ', L.exit[0] - 4, L.exit[1], Math.PI / 2, 3, 6.5); decal('↑', 64, 36, Math.PI / 2, 2, 5);
    decal('大型', L.truck.aisle, 30, Math.PI, 3, 5); decal('大型', L.truck.aisle, -30, 0, 3, 5);
    decal('小型', -35, -40, Math.PI / 2, 2, 3.5); decal('小型', -35, 40, -Math.PI / 2, 2, 3.5);
    for (const ax of L.carAisles) decal('↑', ax, 36, Math.PI, 2, 5);
    decal('徐行', -73, 20, 0, 2.6, 4.5); decal('↑', -73, -30, Math.PI, 2, 5); decal('↑', -10, -46.5, Math.PI / 2, 2, 5);
