    const ledOn = this.night(new THREE.MeshStandardMaterial({ color: 0x333333, emissive: 0xf4f6ff, emissiveIntensity: 0 }), 0, 3);
    const poolMat = this.night(new THREE.MeshBasicMaterial({ map: glowTexture(), color: 0xffc888, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -6 }), 0, 0.95);
