      const list = pools.filter(p => p[3] === kind); if (!list.length) continue;
      const im = new THREE.InstancedMesh(poolGeo, kind ? poolMatW : poolMat, list.length);
      const m4 = new THREE.Matrix4();
      list.forEach((p, i) => { m4.makeScale(p[4], 1, p[4]); m4.setPosition(p[0], p[1], p[2]); im.setMatrixAt(i, m4); });
